'use strict';
const test=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');const vm=require('node:vm');
const root=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(root,'index.html'),'utf8');
function segment(a,b){const first=html.indexOf(a),end=html.indexOf(b,first+1);assert(first>=0&&end>first,`Missing ${a}`);return html.slice(first,end);}
const reportSource=segment('function issueDiagnosticValue(', 'function showPendingRunSaveIssue(');
function harness(){
 let mem={};let downloaded=[];let shown=[];let calls=[];
 const ctx={console,Date,Set,Blob,APP_UI_VERSION:'8.1.12.324',DATA_SCHEMA_VERSION:26,
   ISSUE_REPORT_SESSION_KEY:'test-issue',latestIssueReportMemory:'',
   location:{pathname:'/PL-Life/index.html'},navigator:{userAgent:'UnitBrowser',platform:'Test',onLine:true},window:{indexedDB:{}},
   sessionStorage:{getItem:k=>mem[k]??null,setItem:(k,v)=>mem[k]=v},
   document:{getElementById:()=>null},
   actionDialogResolver:null,queuedContextIssues:[],
   showToast:(...a)=>shown.push(a),
   downloadBlobFile:(blob,name)=>{downloaded.push({blob,name});return true},
   openActionDialog:(...a)=>{calls.push(a);return Promise.resolve('ok');}};
 vm.createContext(ctx);vm.runInContext(reportSource,ctx);
 return {ctx,mem,downloaded,shown,calls};
}
const PII=['PRIVATE_PERSON_NAME_2026','C:\\Users\\PRIVATE\\Desktop\\secret-file.xlsx','联系电话13987654321','secret-private-PC.xlsx','PL收集梦想生活_自动备份_2026-09-19.zip','private-log-EXACT-TEXT'];
const error={name:'AbortError',message:PII.join(' '),plStorageFailure:'browser-database-unreadable',plDbDiagnostic:{label:PII[0],oldVersion:0,newVersion:3,currentStep:PII[5],completedSteps:PII,transactionError:'NotReadableError: '+PII.join(' '),handlerError:'AbortError: '+PII[3]}};
test('controlled native crash reports outer and underlying error type independently',()=>{const {ctx}=harness();const item=ctx.plBuildDiagnosticIncident({error,module:'PC_ATTACHMENT_STORAGE',phase:'预检 PC 附件数据库',writeState:'not-started',source:'openPcMediaDbAtVersion / indexedDbUpgradeError'});const rep=ctx.buildIssueReport({area:'设置 → 恢复资料',status:PII.join(' '),incident:item,diagnostics:'问题编号：DEVICE-MIGRATION-RESTORE\n错误类型：AbortError'});assert.match(rep,/IDB_BACKING_STORE_UNREADABLE/);assert.match(rep,/底层异常：NotReadableError/);assert.match(rep,/外层异常：AbortError/);assert.match(rep,/事务提交状态：未开始写入/);});
for (const [i,sensitive] of PII.entries())test(`portable report excludes sensitive specimen ${i+1}`,()=>{const {ctx}=harness();const item=ctx.plBuildDiagnosticIncident({error,module:'PC_ATTACHMENT_STORAGE',source:'openPcMediaDbAtVersion / indexedDbUpgradeError'});const rep=ctx.buildIssueReport({area:'PC 档案 → '+sensitive,action:sensitive,status:sensitive,next:sensitive,diagnostics:`问题编号：PRIVACY-TEST\n原始异常：${sensitive}`,incident:item});assert(!rep.includes(sensitive),`leak: ${sensitive}`)});
test('unstructured legacy errors cannot export freeform status or raw stack',()=>{const {ctx}=harness();const payload='用户笔记内容：TOP_SECRET_STORY_RED';const result=ctx.buildIssueReport({area:'跑团记录 → '+payload,action:'删除'+payload,status:payload,next:payload,diagnostics:`问题编号：RECORD-SAVE-ERROR\n错误类型：AbortError\n${payload}`});assert.match(result,/诊断未接入|旧入口尚未接入/);assert.doesNotMatch(result,/TOP_SECRET_STORY_RED/);assert.match(result,/RECORD-SAVE-ERROR/);});
test('unknown uncontrolled source is not passed into portable diagnostics',()=>{const {ctx}=harness();const item=ctx.plBuildDiagnosticIncident({error:new Error('fail'),module:'BACKUP_POSTRELOAD',source:'importAnyBackup → '+PII[0],writeState:'read-only'});const rep=ctx.buildIssueReport({incident:item,diagnostics:'问题编号：BACKUP-POSTRELOAD'});assert.doesNotMatch(rep,/PRIVATE_PERSON_NAME_2026/);assert.match(rep,/程序观测位置：importAnyBackup → restore transaction/);});
test('unknown write-state is represented as unverified instead of guessed success',()=>{const {ctx}=harness();const item=ctx.plDiagnoseOperation('PC_EXCEL_BATCH',{writeState:'private_user_file.xlsx',phase:'private phase'});const rep=ctx.buildIssueReport({incident:item});assert.match(rep,/状态代码未受控，需人工核对/);assert.doesNotMatch(rep,/private_user_file.xlsx|private phase/);});
for(const [state,want] of [['not-started','未开始写入'],['committed-readback-unverified','主档案已提交；附件回读未确认'],['committed-render-failed','主档案已提交；显示更新失败'],['verified-rollback','回滚已回读核验'],['read-only','只读操作']])test(`write status ${state} is not collapsed into generic failure`,()=>{const {ctx}=harness();const item=ctx.plDiagnoseOperation('PC_EXCEL_BATCH',{writeState:state});assert.match(ctx.buildIssueReport({incident:item}),new RegExp(want));});
test('queued dialog preserves exact structured incident rather than dropping writeState',()=>{const {ctx,mem}=harness();ctx.actionDialogResolver=()=>{};ctx.showContextIssue({level:'critical',title:'问题',area:'PC 档案 → '+PII[0],action:'保存',status:'提交成功后回读失败',incident:ctx.plDiagnoseOperation('PC_EXCEL_BATCH',{writeState:'committed-readback-unverified'}),diagnostics:'问题编号：PC-EXCEL-BATCH-POSTCOMMIT'});assert.equal(ctx.queuedContextIssues.length,1);assert.equal(ctx.queuedContextIssues[0].incident.writeState,'committed-readback-unverified');assert.doesNotMatch(mem['test-issue'],/PRIVATE_PERSON_NAME_2026/);});
test('legacy diagnostic download is rebuilt, not exported verbatim',()=>{const {ctx,downloaded}=harness();const raw='问题编号：PC-MEDIA-IMPORT\n原始异常：'+PII.join(' // ');ctx.downloadIssueReportText(raw);assert.equal(downloaded.length,1);const obj=downloaded[0];assert.match(obj.name,/PC-MEDIA-IMPORT/);assert.equal(obj.blob.type,'text/plain;charset=utf-8');return obj.blob.text().then(text=>{for(const v of PII)assert(!text.includes(v));assert.match(text,/diagnostic-v2/);});});
test('legacy persisted report history is ignored, not re-exported',()=>{const {ctx,mem}=harness();mem['test-issue']=JSON.stringify([{time:123,report:'OLD PRIVATE RECORD '+PII[0]}]);assert.equal(ctx.latestIssueReport(),'');ctx.persistIssueReport('问题编号：TEST-OLD\n'+PII[0],{area:PII[0]});assert.doesNotMatch(mem['test-issue'],/PRIVATE_PERSON_NAME_2026/);assert.match(ctx.latestIssueReport(),/diagnostic-v2/);});
test('portable report never stores private record title in session metadata',()=>{const {ctx,mem}=harness();ctx.persistIssueReport(ctx.buildIssueReport({area:'模组档案 → private module',diagnostics:'问题编号：MODULE-ERROR'}),{title:PII[0],area:'模组档案 → '+PII[0]});assert.doesNotMatch(mem['test-issue'],/PRIVATE_PERSON_NAME_2026/);});
test('media ZIP and gallery errors now include controlled fault sources',()=>{for(const code of ['PC_MEDIA_IMPORT','PC_GALLERY_DOWNLOAD','PC_EXCEL_BATCH_PREVIEW']){const r=harness().ctx.plDiagnoseOperation(code,{error:new Error(PII[0])});assert.match(r.source,/ → /);assert.notEqual(r.classification,'UNCLASSIFIED_OPERATION_FAILURE');}});
test('media upload and gallery download do not concatenate user filename into portable diagnostics',()=>{// Verify the controlled diagnostic call sites without requiring a guessed function name.
assert.match(html,/plDiagnoseOperation\('PC_GALLERY_DOWNLOAD'/);assert.match(html,/plDiagnoseOperation\('PC_MEDIA_IMPORT'/);
});
test('session and download code explicitly protect legacy reports',()=>{for(const token of ['plReportForDownload(source)','rows.find(row=>plIsV2PortableReport','rows.filter(row=>plIsV2PortableReport'])assert(html.includes(token));});
